Certainly! Here's a simple implementation:

In `identifier.js`:
```javascript
function isExactIdentifier(input, registry) {
    return registry.includes(input);
}

module.exports = isExactIdentifier;
```

And in `registry.js`, you can use it like this:
```javascript
const isExactIdentifier = require('./utils/identifier');
const identifiers = ['config1', 'config2', 'config3'];

const checkIdentifier = 'config2';
console.log(isExactIdentifier(checkIdentifier, identifiers)); // true
```

